      "summary": "首页 > 党建与科学文化 > 工作动态 6月29日，中国科学院新疆分院分党组召开理论学习中心组（扩大）专题学习会暨树立和践行正确政绩观学习教育第四期读书班。 会议提出，习近平党建思想内涵丰富、体系严密，是加强新时代党的建设的根本遵循，为我们更好履行国家战略科技力量主力军职责使命、加快抢占科技制高点提供了重要指导、指明了",
